import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"网站 / Node","description":"分发的是安装包对象，不能用来刷新网页升级站点。浏览器网页不能用 TypeScript SDK。","frontmatter":{"title":"网站 / Node","description":"分发的是安装包对象，不能用来刷新网页升级站点。浏览器网页不能用 TypeScript SDK。"},"headers":[],"relativePath":"guide/scenarios/web-node.md","filePath":"guide/scenarios/web-node.md","lastUpdated":1790057721000}`),a={name:`guide/scenarios/web-node.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="网站-node" tabindex="-1">网站 / Node <a class="header-anchor" href="#网站-node" aria-label="Permalink to “网站 / Node”">​</a></h1><p>KiriVers 分发的是<strong>安装包对象</strong>（SHA-256 文件），不能把「刷新网页」当成站点升级通道。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h2><ul><li>站点静态资源、SPA 构建产物：用自己的 CDN / 流水线，不要走 KiriVers check。</li><li>同仓里的 <strong>Node 服务进程</strong>（守护进程、CLI）：走原生 JSON <strong>POST</strong> check。</li><li>桌面壳（Electron）包住网站：安装包走 <a href="./electron">Electron</a> listing 或壳内自制客户端。</li></ul><p>官方 TypeScript SDK <strong>没有</strong> browser export，不能在浏览器里调用 check。</p><h2 id="配置入口" tabindex="-1">配置入口 <a class="header-anchor" href="#配置入口" aria-label="Permalink to “配置入口”">​</a></h2><p>Node 进程：项目 <strong>设置</strong> 的速率限制 / Token，以及 <a href="/guide/features/check">检查更新</a>。Electron 壳：项目 <strong>设置 → 商店协议</strong> → <strong>新建上架</strong>。</p><h2 id="客户端职责" tabindex="-1">客户端职责 <a class="header-anchor" href="#客户端职责" aria-label="Permalink to “客户端职责”">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>做法</th></tr></thead><tbody><tr><td>浏览器里的网页应用</td><td>不要使用 TypeScript SDK。站点静态资源用自己的 CDN / 构建流水线</td></tr><tr><td>Node 服务端程序</td><td>按 <a href="./server-cli">服务与命令行</a> <strong>POST</strong> check</td></tr><tr><td>Electron 壳</td><td><a href="./electron">Electron</a> 商店 listing，或壳内自制客户端走原生 JSON</td></tr></tbody></table><h2 id="故障" tabindex="-1">故障 <a class="header-anchor" href="#故障" aria-label="Permalink to “故障”">​</a></h2><p>浏览器里 <code>import</code> 官方 SDK 会失败（无 browser 构建）。把站点 HTML 当「安装包」上传后，刷新网页也不会走 check。Node 进程必须 <strong>POST</strong>；GET check 是 404。</p><p>相关：<a href="/guide/features/check">检查更新</a>、<a href="/api/sdk/">SDK</a>。</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};